class BoundedBuffer<T> {
    private final Lock lock = new ReentrantLock();
    private final Condition notFull = lock.newCondition();
    private final Condition notEmpty = lock.newCondition();
    private final Deque<T> q = new ArrayDeque<>(); private final int cap = 100;

    void put(T t) throws InterruptedException {
        lock.lock();
        try { while (q.size() == cap) notFull.await();   // while 防虚假唤醒
              q.add(t); notEmpty.signal(); }               // 只唤醒消费者
        finally { lock.unlock(); }
    }
    T take() throws InterruptedException {
        lock.lock();
        try { while (q.isEmpty()) notEmpty.await();
              T t = q.poll(); notFull.signal(); return t; }
        finally { lock.unlock(); }
    }
}

class RuleCache {
    private final ReadWriteLock rw = new ReentrantReadWriteLock();
    private Map<String, Rule> rules = new HashMap<>();

    Rule get(String key) {
        rw.readLock().lock();                    // 多个读线程并发
        try { return rules.get(key); } finally { rw.readLock().unlock(); }
    }
    void reload(Map<String, Rule> fresh) {
        rw.writeLock().lock();                   // 写时独占
        try { rules = new HashMap<>(fresh); } finally { rw.writeLock().unlock(); }
    }
}
