void gracefulShutdown(ExecutorService pool) {
    pool.shutdown();                                       // 不再接收新任务
    try {
        if (!pool.awaitTermination(30, TimeUnit.SECONDS)) {
            List<Runnable> dropped = pool.shutdownNow();   // 强制中断
            log.warn("dropped {} tasks", dropped.size());
            pool.awaitTermination(10, TimeUnit.SECONDS);
        }
    } catch (InterruptedException e) {
        pool.shutdownNow();
        Thread.currentThread().interrupt();                // 恢复中断状态
    }
}

public class TransferService {

    // 破坏循环等待：按账户 ID 排序后加锁
    public void transfer(Account from, Account to, long amount) {
        Account first  = from.getId() < to.getId() ? from : to;
        Account second = first == from ? to : from;
        synchronized (first) {
            synchronized (second) {
                from.debit(amount);
                to.credit(amount);
            }
        }
    }

    // 破坏不可剥夺：tryLock 超时后释放已持有的锁并重试
    public boolean transferWithTimeout(Account from, Account to, long amount) throws InterruptedException {
        long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(1);
        while (System.nanoTime() < deadline) {
            if (from.lock().tryLock(50, TimeUnit.MILLISECONDS)) {
                try {
                    if (to.lock().tryLock(50, TimeUnit.MILLISECONDS)) {
                        try { from.debit(amount); to.credit(amount); return true; }
                        finally { to.lock().unlock(); }
                    }
                } finally { from.lock().unlock(); }
            }
            Thread.sleep(ThreadLocalRandom.current().nextInt(10));   // 随机退避避免活锁
        }
        return false;
    }
}

